```javascript
<template>
    <div id="main" class="charts-content"></div>
</template>
<script setup>
    import { ref, unref, onMounted } from "vue";
          import { message, Input } from "ant-design-vue";
          import { ctx, utils } from "byteluck-driven-vue";
          const http = utils.getHttp();
          const isMobile = utils.getDevice() === "mobile";
          const props = defineProps({
            pageStatus: String,
            name: String,
          });
          const emit = defineEmits(["change"]);
          const initCharts=()=>{
             let url = 'https://cdnjs.cloudflare.com/ajax/libs/echarts/5.4.1/echarts.min.js';
            let jsapi = document.createElement('script');
            jsapi.charset = 'utf-8';
            jsapi.src = url;
                jsapi.onload = async () => {
                drawCharts()
                }
            document.head.appendChild(jsapi);
          }
        const drawCharts=()=>{
                var chartDom = document.getElementById('main');
                var myChart = echarts.init(chartDom);
                var option;
                option = {
                xAxis: {
                    type: 'category',
                    data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
                },
                yAxis: {
                    type: 'value'
                },
                series: [
                    {
                    data: [150, 230, 224, 218, 135, 147, 260],
                    type: 'line'
                    }
                ]
                };
                option && myChart.setOption(option);
        }
          onMounted(() => {
            initCharts()
          });
</script>
<style scoped>
    .charts-content {
        width: 200px;
        height: 200px;
    }
</style>
