    public LeftVariableBo(String type, String value) {
        this.type = type;
        this.value = value;
    }

}

/**
 * 数据过滤右值对象
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class RightVariableBo implements Serializable {

    private static final long serialVersionUID = 1860415281232802560L;

    /**
     * 类型
