    onMounted(async () => {
      await nextTick();
      resetStyle();
      addAnimation();
    });

    onUnmounted(() => {
      removeAnimation();
    })

    function handleTabTypes(type, idx) {
      currentType.value = type;
      index.value = idx;
    }

    function handleAllocation(row) {
      proxy.$message.success('调拨请求成功')
    }

    function handleAddTask(row) {
