  function hideDecision(wctype) {
    hideDecisionSubmitButton(wctype)
    document.addEventListener(wctype + '-result', () => {
        setTimeout(() => {
          hideDecisionSubmitButton(wctype)
        })
    })
  }
  //获取到隐藏 老组件wfc-decision，新组件wfc-decision
  hideDecision('wfc-decision')
  hideDecision('bla-decision')
}
