## 8.createFormBaseFields 组件为表单控件（form）时内置fields 👇

注：createFormBaseFields 中包含 createBaseFields中的所有属性


```typescript
/**
  接收自定义属性的默认值
*/
createFormBaseFields({
    placeholder: '请选择',
})


内置自定义控件属性
/**
* dataBind: 绑定数据项名称
* caption：标题
* isHideCaption：隐藏标题
* labelPosition：标题布局
* defaultState：默认状态
* required：设置
* placeholder: 提示文字
*/
return [
  ...createBaseFields(),
    {
      type: 'DataBind',
      key: 'dataBind',
      component: 'data-bind',
      defaultValue: defaultValues?.dataBind,
    },
    {
      key: 'caption',
      type: 'string',
      component: 'input',
      props: {
        maxLength: 80,
        i18n: true,
      },
      defaultValue: defaultValues?.caption,
      validator(value: string) {
        if (!value) {
          return '标题必填'
        }
      },
    },
    {
      label: '隐藏标题',
      key: 'isHideCaption',
      type: 'boolean',
      component: 'switch',
      defaultValue: defaultValues?.isHideCaption,
      props: {
        showType: 'checkbox',
      },
      // 在明细表内隐藏
      scopeEffect(driven: any, payload: any) {
        if (payload.current?.type !== payload.from.type) {
          driven.setInstance(
            payload.control,
            'isHideCaption',
            payload.current.type === 'subtable'
          )
          return {
            visible: payload.current.type !== 'subtable',
          }
        }
      },
    },
    {
      key: 'labelPosition',
      type: 'string',
      component: 'radio',
      defaultValue: defaultValues?.labelPosition,
      props: {
        showType: 'solid',
        options: [
          { label: '上下布局', value: 'top' },
          { label: '左右布局', value: 'left' },
        ],
      },
    },
    {
      key: 'defaultState',
      type: 'string',
      component: 'radio',
      defaultValue: defaultValues?.defaultState,
      props: {
        showType: 'solid',
        options: [
          { label: '普通', value: 'default' },
          { label: '只读', value: 'readonly' },
        ],
      },
    },
    {
      label: '必填',
      key: 'required',
      type: 'boolean',
      component: 'switch',
      defaultValue: defaultValues?.required,
    },
    {
      label: '提示文字',
      key: 'placeholder',
      type: 'string',
      component: 'input',
      defaultValue: defaultValues?.placeholder,
      props: {
        maxLength: 80,
        i18n: true,
      },
    },
  ]
